INSERT INTO remediation_methods(code,name,category,purpose,application_conditions,advantages,limitations,source_url) VALUES ('MONITOR','Повторний моніторинг','monitoring','Уточнення концентрацій та просторових меж забруднення','За неповних, неперевірених або давніх даних; для контролю змін','Допомагає встановити надійність висновків','Не очищує ґрунт','https://www.frtr.gov/matrix/Full-Matrix/') ON CONFLICT(code) DO UPDATE SET name=EXCLUDED.name,category=EXCLUDED.category,purpose=EXCLUDED.purpose,application_conditions=EXCLUDED.application_conditions,advantages=EXCLUDED.advantages,limitations=EXCLUDED.limitations,source_url=EXCLUDED.source_url;
INSERT INTO remediation_methods(code,name,category,purpose,application_conditions,advantages,limitations,source_url) VALUES ('SOURCE','Контроль джерела забруднення','prevention','Запобігання подальшому надходженню металів','За підтвердженого або ймовірного активного джерела','Впливає на причину подальшого забруднення','Потрібно встановити та контролювати джерело','https://www.frtr.gov/matrix/Full-Matrix/') ON CONFLICT(code) DO UPDATE SET name=EXCLUDED.name,category=EXCLUDED.category,purpose=EXCLUDED.purpose,application_conditions=EXCLUDED.application_conditions,advantages=EXCLUDED.advantages,limitations=EXCLUDED.limitations,source_url=EXCLUDED.source_url;
INSERT INTO remediation_methods(code,name,category,purpose,application_conditions,advantages,limitations,source_url) VALUES ('PHYTOEXT','Фітоекстракція','remediation','Поступове вилучення частини доступних металів рослинами','Підтверджене забруднення, сумісна рослинність, доступність забруднювачів','Менше технічне втручання у ґрунт','Повільна; ефективність залежить від виду рослин і металу; контроль біомаси','https://frtr.gov/matrix/Phytoremediation/') ON CONFLICT(code) DO UPDATE SET name=EXCLUDED.name,category=EXCLUDED.category,purpose=EXCLUDED.purpose,application_conditions=EXCLUDED.application_conditions,advantages=EXCLUDED.advantages,limitations=EXCLUDED.limitations,source_url=EXCLUDED.source_url;
INSERT INTO remediation_methods(code,name,category,purpose,application_conditions,advantages,limitations,source_url) VALUES ('PHYTOSTAB','Фітостабілізація','remediation','Зменшення перенесення та доступності металів шляхом рослинного покриву','За умов, що дозволяють створити рослинний покрив','Може обмежувати ерозію та пилове перенесення','Метали залишаються у ґрунті; потрібне підтримання покриву','https://frtr.gov/matrix/Phytoremediation/') ON CONFLICT(code) DO UPDATE SET name=EXCLUDED.name,category=EXCLUDED.category,purpose=EXCLUDED.purpose,application_conditions=EXCLUDED.application_conditions,advantages=EXCLUDED.advantages,limitations=EXCLUDED.limitations,source_url=EXCLUDED.source_url;
INSERT INTO remediation_methods(code,name,category,purpose,application_conditions,advantages,limitations,source_url) VALUES ('IMMOB','Іммобілізація металів','remediation','Зменшення рухомості/вилуговування металів добавками','Підтверджене забруднення; необхідні дані про властивості ґрунту і тестування реагентів','Може зменшити міграцію та доступність металів','Не вилучає загальний вміст; ефект слід контролювати','https://frtr.gov/matrix/Solidification-and-Stabilization/') ON CONFLICT(code) DO UPDATE SET name=EXCLUDED.name,category=EXCLUDED.category,purpose=EXCLUDED.purpose,application_conditions=EXCLUDED.application_conditions,advantages=EXCLUDED.advantages,limitations=EXCLUDED.limitations,source_url=EXCLUDED.source_url;
INSERT INTO remediation_methods(code,name,category,purpose,application_conditions,advantages,limitations,source_url) VALUES ('PHADJUST','Регулювання кислотності','remediation','Коригування pH для зниження рухомості окремих металів','Кислий ґрунт і підтверджена доцільність за хімічними характеристиками','Може зменшувати доступність окремих металів','Не вилучає метали; ризик небажаних змін ґрунту','https://www.frtr.gov/matrix/Full-Matrix/') ON CONFLICT(code) DO UPDATE SET name=EXCLUDED.name,category=EXCLUDED.category,purpose=EXCLUDED.purpose,application_conditions=EXCLUDED.application_conditions,advantages=EXCLUDED.advantages,limitations=EXCLUDED.limitations,source_url=EXCLUDED.source_url;
INSERT INTO remediation_methods(code,name,category,purpose,application_conditions,advantages,limitations,source_url) VALUES ('WASH','Промивання ґрунту','remediation','Вилучення частини забруднювачів із ґрунтового матеріалу','Підтверджене забруднення; гранулометрія та технічна придатність','Може видаляти забруднювачі, особливо з придатних фракцій','Потребує очищення стоків; дрібнозернистий ґрунт складний','https://frtr.gov/matrix/Soil-Washing/') ON CONFLICT(code) DO UPDATE SET name=EXCLUDED.name,category=EXCLUDED.category,purpose=EXCLUDED.purpose,application_conditions=EXCLUDED.application_conditions,advantages=EXCLUDED.advantages,limitations=EXCLUDED.limitations,source_url=EXCLUDED.source_url;
INSERT INTO remediation_methods(code,name,category,purpose,application_conditions,advantages,limitations,source_url) VALUES ('EXCAV','Локальне вилучення ґрунту','remediation','Видалення локально забрудненого матеріалу','Підтверджена локалізація та обсяг; можливість безпечного поводження','Швидко усуває забруднений матеріал із конкретної ділянки','Витрати, транспортування і подальше поводження з відходами','https://frtr.gov/matrix/Excavation-and-Off-Site-Disposal/') ON CONFLICT(code) DO UPDATE SET name=EXCLUDED.name,category=EXCLUDED.category,purpose=EXCLUDED.purpose,application_conditions=EXCLUDED.application_conditions,advantages=EXCLUDED.advantages,limitations=EXCLUDED.limitations,source_url=EXCLUDED.source_url;
INSERT INTO remediation_methods(code,name,category,purpose,application_conditions,advantages,limitations,source_url) VALUES ('LANDUSE','Обмеження землекористування','prevention','Зниження контакту людей із забрудненим ґрунтом','За потенційної експозиції та обґрунтованого обмеження діяльності','Може швидко скоротити контакт','Забруднення не ліквідує; потрібне дотримання обмежень','https://www.frtr.gov/matrix/Full-Matrix/') ON CONFLICT(code) DO UPDATE SET name=EXCLUDED.name,category=EXCLUDED.category,purpose=EXCLUDED.purpose,application_conditions=EXCLUDED.application_conditions,advantages=EXCLUDED.advantages,limitations=EXCLUDED.limitations,source_url=EXCLUDED.source_url;
